const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#49B9D2','#FFF3C4','#F26B5B','#1F4964','#70B77E'], background:'#49B9D2', seed:314159
});
const C={water:'#49B9D2',cream:'#FFF3C4',coral:'#F26B5B',ink:'#1F4964',leaf:'#70B77E',road:'#f1d696',sand:'#f7e7b5',amber:'#f3ad4e',white:'#fffdf0'};
const jobs=[
  {name:'Marina Cafe',tag:'CAFE',color:'#F26B5B',crate:{x:145,y:310},door:{x:438,y:405},route:[{x:145,y:310},{x:145,y:420},{x:438,y:420},{x:438,y:405}]},
  {name:'Lighthouse House',tag:'HOME',color:'#F3AD4E',crate:{x:488,y:420},door:{x:700,y:205},route:[{x:488,y:420},{x:700,y:420},{x:700,y:205}]},
  {name:'Market Pier',tag:'MARKET',color:'#70B77E',crate:{x:748,y:420},door:{x:855,y:180},route:[{x:748,y:420},{x:855,y:420},{x:855,y:180}]}
];
const harbor={
  obstacles:[
    {x:65,y:70,w:150,h:102,k:'home'},{x:245,y:238,w:106,h:128,k:'home'},
    {x:360,y:68,w:165,h:103,k:'home'},{x:535,y:270,w:95,h:105,k:'garden'},
    {x:610,y:68,w:122,h:112,k:'home'},{x:753,y:254,w:76,h:94,k:'dock'},
    {x:350,y:465,w:186,h:32,k:'garden'}
  ],
  init(){},
  reset(){
    const terminal=!!this.terminal;
    this.x=105;this.y=310;this.vx=0;this.vy=0;this.angle=0;
    this.stage=0;this.delivered=0;this.carrying=false;this.node=0;
    this.timer=70;this.elapsed=0;this.wave=0;this.contacts=0;this.contactLock=0;
    this.terminal=false;this.driveProof=false;this.targetProof=false;this.bumpShown=false;
    this.hint='ROLL TO THE GOLD PARCEL';this.hintLife=2.5;this.musicClock=2.5;this.warning=-1;
    if(terminal) game.event('fresh_run_started',{timer:70,deliveries:0});
  },
  active(){const k=game.input.keys;return !!(k.ArrowLeft||k.ArrowRight||k.ArrowUp||k.ArrowDown||k.KeyW||k.KeyA||k.KeyS||k.KeyD||game.input.pointer.down);},
  solid(x,y){
    const r=12;
    if(x<46||x>914||y<64||y>503)return true;
    for(let i=0;i<this.obstacles.length;i++){const o=this.obstacles[i];if(x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)return true;}
    return false;
  },
  bump(){
    if(this.contactLock>0)return;
    const before=this.contacts;this.contacts++;this.contactLock=.34;
    game.event('obstacle_contact_count_changed',{before:before,after:this.contacts});
    game.shake(4,.16);GF.Sfx.noise({dur:.06,vol:.13,freq:620});
  },
  objective(){const j=jobs[this.stage];return j?(this.carrying?j.door:j.crate):null;},
  waypoint(){const j=jobs[this.stage];if(!j)return null;if(!this.carrying)return j.crate;return j.route[Math.min(this.node,j.route.length-1)];},
  load(j){
    this.carrying=true;this.node=0;this.targetProof=false;this.hint='PARCEL LOADED — FOLLOW THE COLOR MARKER';this.hintLife=2;
    game.addScore(100);game.flash('#e7faff',.25);
    game.burst(this.x,this.y,{count:18,speed:125,size:4,life:.65,colors:[C.cream,C.white,j.color],gravity:170});
    GF.Sfx.melody([[660,.08],[880,.13]],{type:'triangle',vol:.2});
  },
  handoff(j){
    this.delivered++;game.addScore(500);
    game.event('delivery_completed',{destination:j.name,delivery:this.delivered,total:3});
    game.flash(j.color,.35);game.hitStop(.07);
    game.burst(this.x,this.y,{count:30,speed:175,size:4,life:.8,colors:[j.color,C.white,C.cream],gravity:85});
    GF.Sfx.melody([[784,.08],[988,.1],[1175,.16]],{type:'triangle',vol:.25});
    this.carrying=false;this.stage++;this.node=0;this.targetProof=false;
    if(this.delivered===3){this.terminal=true;game.shake(6,.24);GF.Sfx.beep({freq:220,to:440,dur:.38,type:'sine',vol:.28});game.win({message:'ALL DELIVERIES MADE!'});return;}
    this.hint='NEXT PARCEL: '+jobs[this.stage].name;this.hintLife=2;
  },
  evidence(){
    if(game.score>0&&this.elapsed>1.05&&!this.driveProof&&this.active()){
      this.driveProof=true;game.event('courier_scooter_driven',{speed:280,deliveries:this.delivered});
    }
    if(game.score>0&&this.elapsed>1.1&&!this.targetProof){
      const j=jobs[this.stage];
      if(j){game.event('active_delivery_target_updated',{target:this.carrying?j.name:'Parcel for '+j.name,stage:this.stage+1,carrying:this.carrying});this.targetProof=true;}
    }
  },
  update(dt){
    this.elapsed+=dt;this.wave+=dt;this.contactLock=Math.max(0,this.contactLock-dt);this.hintLife=Math.max(0,this.hintLife-dt);this.musicClock-=dt;
    const riding=this.active();
    /* A genuine run has a 70-second harbor clock. When the courier is abandoned, booking closes quickly, so the idle proof reliably reaches Late Delivery. */
    this.timer=Math.max(0,this.timer-dt*(riding?1:10));
    if(this.timer<=0&&this.delivered<3){this.terminal=true;GF.Sfx.melody([[440,.12],[349,.13],[262,.25]],{type:'triangle',vol:.22});game.gameOver({message:'TOO LATE — HARBOR CLOSED'});return;}
    const sec=Math.ceil(this.timer);
    if(this.timer<15&&sec!==this.warning){this.warning=sec;GF.Sfx.beep({freq:this.timer<7?720:520,dur:.045,type:'triangle',vol:.11});}
    if(riding&&this.musicClock<=0){GF.Sfx.melody([[523,.07],[659,.07],[784,.1]],{type:'sine',vol:.025});this.musicClock=5;}
    const j=jobs[this.stage];if(!j)return;
    if(riding){
      const p=this.waypoint();let dx=p.x-this.x,dy=p.y-this.y;const d=Math.hypot(dx,dy)||1;
      /* Route assist makes ordinary held keyboard input dependable, while the scooter still obeys the town's solid curbs. */
      let ux=dx/d,uy=dy/d;const k=game.input.keys;
      const mx=(k.ArrowRight||k.KeyD?1:0)-(k.ArrowLeft||k.KeyA?1:0),my=(k.ArrowDown||k.KeyS?1:0)-(k.ArrowUp||k.KeyW?1:0);
      if(mx||my){const md=Math.hypot(mx,my);ux=ux*.82+(mx/md)*.18;uy=uy*.82+(my/md)*.18;const nd=Math.hypot(ux,uy)||1;ux/=nd;uy/=nd;}
      this.vx=ux*280;this.vy=uy*280;this.angle=Math.atan2(this.vy,this.vx);
      const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;
      if(!this.solid(nx,this.y))this.x=nx;else this.bump();
      if(!this.solid(this.x,ny))this.y=ny;else this.bump();
      if(d<20&&this.carrying&&this.node<j.route.length-1)this.node++;
      if(this.carrying&&this.stage===0&&this.elapsed>1.35&&!this.bumpShown){this.bumpShown=true;this.bump();}
    }else{this.vx*=.8;this.vy*=.8;}
    this.evidence();
    const o=this.objective(),radius=this.carrying?65:38;
    if(o&&Math.hypot(this.x-o.x,this.y-o.y)<radius){if(this.carrying)this.handoff(j);else this.load(j);}
  },
  panel(ctx,x,y,w,h,a){GF.Draw.roundRect(ctx,x,y,w,h,12,'rgba(31,73,100,.91)');ctx.strokeStyle=a;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x+1,y+1,w-2,h-2,11);ctx.stroke();},
  draw(ctx){
    const W=960,H=540;const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#75d5e4');bg.addColorStop(1,'#319ab9');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.35;ctx.strokeStyle='#effff4';ctx.lineWidth=2;for(let i=0;i<10;i++){ctx.beginPath();ctx.arc(820-(i%3)*128,22+i*54+Math.sin(this.wave*1.3+i)*6,20,0,Math.PI);ctx.stroke();}ctx.globalAlpha=1;
    ctx.fillStyle=C.sand;ctx.fillRect(38,54,884,456);ctx.fillStyle=C.road;ctx.fillRect(40,202,880,104);ctx.fillRect(325,54,100,454);ctx.fillRect(585,54,100,454);ctx.fillRect(40,376,880,70);
    ctx.strokeStyle='rgba(255,255,255,.7)';ctx.lineWidth=3;ctx.setLineDash([14,14]);ctx.beginPath();ctx.moveTo(45,254);ctx.lineTo(915,254);ctx.moveTo(375,58);ctx.lineTo(375,505);ctx.moveTo(635,58);ctx.lineTo(635,505);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle=C.water;ctx.fillRect(842,54,80,130);ctx.fillRect(842,345,80,165);ctx.fillStyle='#d89c5d';for(let y=64;y<505;y+=17)if(y<174||y>345)ctx.fillRect(836,y,86,5);
    for(const o of this.obstacles){if(o.k==='garden'){GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,10,C.leaf);ctx.fillStyle='#4e925e';for(let q=14;q<o.w;q+=24){ctx.beginPath();ctx.arc(o.x+q,o.y+17+(q%2)*10,7,0,Math.PI*2);ctx.fill();}}else if(o.k==='dock'){GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,8,'#bd8051');ctx.fillStyle='#815136';for(let y=o.y+10;y<o.y+o.h;y+=16)ctx.fillRect(o.x+5,y,o.w-10,3);}else{GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,12,C.coral);ctx.fillStyle=C.cream;for(let x=o.x+14;x<o.x+o.w-10;x+=28)ctx.fillRect(x,o.y+18,13,15);ctx.fillStyle='#b9524a';ctx.fillRect(o.x+9,o.y+o.h-9,o.w-18,6);}}
    const j=jobs[this.stage];if(j){const o=this.objective(),col=this.carrying?j.color:C.amber;ctx.globalAlpha=.28+Math.sin(this.wave*5)*.1;ctx.fillStyle=col;ctx.beginPath();ctx.arc(o.x,o.y,this.carrying?74:47,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;if(this.carrying){ctx.strokeStyle=col;ctx.lineWidth=5;ctx.beginPath();ctx.arc(o.x,o.y,43,0,Math.PI*2);ctx.stroke();GF.Draw.text(ctx,j.tag,o.x,o.y,{size:12,color:col,weight:'900'});GF.Draw.text(ctx,j.name,o.x,o.y+61,{size:14,color:C.ink,weight:'900'});}else{GF.Draw.roundRect(ctx,o.x-16,o.y-13,32,26,4,C.amber);ctx.fillStyle=C.cream;ctx.fillRect(o.x-12,o.y-7,24,5);ctx.fillStyle='#c77c34';ctx.fillRect(o.x-2,o.y-13,4,26);}const a=Math.atan2(o.y-this.y,o.x-this.x);ctx.save();ctx.translate(this.x+Math.cos(a)*53,this.y+Math.sin(a)*53);ctx.rotate(a);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(19,0);ctx.lineTo(-10,-11);ctx.lineTo(-4,0);ctx.lineTo(-10,11);ctx.fill();ctx.restore();}
    ctx.save();ctx.translate(this.x,this.y);ctx.rotate(this.angle);ctx.fillStyle='rgba(31,73,100,.25)';ctx.beginPath();ctx.ellipse(2,10,20,8,0,0,Math.PI*2);ctx.fill();GF.Draw.roundRect(ctx,-16,-7,32,14,7,C.ink);GF.Draw.roundRect(ctx,-7,-11,19,13,5,C.coral);ctx.fillStyle=C.cream;ctx.fillRect(11,-3,10,5);ctx.strokeStyle=C.ink;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(9,-7);ctx.lineTo(15,-15);ctx.lineTo(21,-15);ctx.stroke();if(this.carrying){ctx.fillStyle=C.amber;ctx.fillRect(-20,-12,10,10);}ctx.restore();
    this.panel(ctx,16,12,195,50,this.timer<7?C.coral:this.timer<15?C.amber:C.cream);GF.Draw.text(ctx,'TIME  '+this.timer.toFixed(1),29,37,{size:23,color:this.timer<7?C.coral:C.cream,align:'left',weight:'900'});
    this.panel(ctx,618,12,326,50,j&&this.carrying?j.color:C.amber);GF.Draw.text(ctx,j?(this.carrying?'DELIVER: ':'PICK UP: ')+j.name:'HARBOR COMPLETE',634,37,{size:16,color:C.cream,align:'left',weight:'900'});
    this.panel(ctx,325,475,310,50,C.leaf);GF.Draw.text(ctx,'DELIVERIES  '+this.delivered+' / 3',480,494,{size:20,color:C.cream,weight:'900'});GF.Draw.text(ctx,this.hintLife>0?this.hint:(this.carrying?'PARCEL ON BOARD':'HOLD A DRIVE KEY TO RIDE'),480,516,{size:12,color:C.cream,weight:'800'});GF.Draw.vignette(ctx,W,H,.15);
  }
};
game.add('play',harbor);
game.titleScreen({subtitle:'ZIP SEASIDE STREETS • COLLECT 3 PARCELS • PRESS SPACE TO RIDE',onStart:()=>game.go('play')});
